const grammar = [
  GR('g_tai_hoshii', { title: 'たい and ほしい: wanting', pattern: 'verb stem + たい です; thing が ほしい です', meaning_en: 'Want to do; want a thing.', explanation: ['To say you want to do something, take the ます-stem and add たい: たべます → たべたい です (I want to eat), いきます → いきたい です.', 'たい behaves like an い-adjective: negative たくない, past たかった. To say you want a thing, use ほしい: スマホ が ほしい です.', 'The object of たい can take を or が: ラーメン を たべたい です.'], structure_notes: 'Stem + たい (です); thing が ほしい (です).', examples: ['s_n5u11_t01', 's_n5u11_t02', 's_n5u11_t04', 's_n5u11_k22'], common_mistakes: ['Using ほしい with a verb.', 'Using たい to talk about another person\'s wishes.'], contrast_with: ['g_i_adjective'], practice_question_ids: gq.tai, register: 'polite', tags: ['desire'] }),
  GR('g_te_form', { title: 'The て-form', pattern: 'verb-て / verb-で', meaning_en: 'A connecting verb form used in requests and more.', explanation: ['The て-form is made from the ます-form stem. Group 2 (る-verbs such as たべます, みます, おきます, ねます, あけます): add て. Group 1 (the others): change the final sound: い/ち/り → って; み/び/に → んで; き → いて; ぎ → いで; し → して. The exception is いきます → いって.', 'Irregular: します → して, きます → きて.', 'The て-form is needed for requests (～て ください) and for many later patterns.'], structure_notes: 'Stem + て/で; see the sound-change table.', examples: ['s_n5u11_t05', 's_n5u11_t06', 's_n5u11_t07', 's_n5u11_t10'], common_mistakes: ['Forgetting the sound change in group 1.', 'Using いて for いきます.'], contrast_with: ['g_masu_forms'], practice_question_ids: gq.te, register: 'neutral', tags: ['verbs'] }),
  GR('g_te_kudasai', { title: 'て-form + ください: please do', pattern: 'verb-て ください', meaning_en: 'Please do (a request).', explanation: ['To ask someone to do something, use the て-form followed by ください: ちょっと まって ください (please wait a moment).', 'Add ゆっくり (slowly) or もういちど (once more) to be clear: ゆっくり はなして ください.', 'Signs often use this form: くつ を ぬいで ください, しずか に して ください.'], structure_notes: 'Verb-て + ください.', examples: ['s_n5u11_t05', 's_n5u11_t07', 's_n5u11_t10', 's_n5u11_t12'], common_mistakes: ['Using the ます-form before ください.'], contrast_with: ['g_wo_object'], practice_question_ids: gq.req, register: 'polite', tags: ['requests'] }),
  GR('g_counting_things', { title: 'Counting things: ひとつ, ふたつ ...', pattern: 'thing を number ください', meaning_en: 'Counts objects up to ten.', explanation: ['Up to ten, things are counted with a native series: ひとつ, ふたつ, みっつ, よっつ, いつつ, むっつ, ななつ, やっつ, ここのつ, とお.', 'The number goes after the thing and its particle: コーヒー を ふたつ ください (two coffees, please).', 'These words count objects, not people.'], structure_notes: 'Thing を count ください.', examples: ['s_n5u11_t13', 's_n5u11_t14', 's_n5u11_t15'], common_mistakes: ['Using さんつ or よんつ.'], contrast_with: ['g_wo_object'], practice_question_ids: gq.ct, register: 'neutral', tags: ['counters'] }),
];

